using System.Security.Cryptography;

namespace Trimme.Modules.Identity.Application.Barbers;

/// <summary>
/// A barber's temporary password (D-146), generated by the server and shown once to the owner (or admin), who hands it
/// to the barber; the barber replaces it at the first sign-in (D-139). Lowercase letters and digits without look-alikes
/// (no 0/o, 1/l/i), so it can be read out or typed on a phone: 12 characters from 31, about 59 bits.
/// </summary>
internal static class TemporaryPasswords
{
    public const string Alphabet = "abcdefghjkmnpqrstuvwxyz23456789";
    public const int Length = 12;

    /// <summary>Identity's password rules (IdentityModule): at least 10 characters, 4 of them different.</summary>
    private const int MinUniqueCharacters = 4;

    public static string New()
    {
        while (true)
        {
            var password = RandomNumberGenerator.GetString(Alphabet, Length);
            if (password.Distinct().Count() >= MinUniqueCharacters)
            {
                return password;
            }
        }
    }
}
